// Rebuilds lib/playbook-html.ts from content/playbook/crossroads-playbook.html.
// The page is served at /admin/<ADMIN_DASH_KEY>/playbook. It is embedded as a
// string module (not read from disk at request time) so Netlify's function
// bundle always carries it. Run after editing the HTML:
//   node scripts/build-playbook.mjs
import { readFileSync, writeFileSync } from "node:fs";

const html = readFileSync(new URL("../content/playbook/crossroads-playbook.html", import.meta.url), "utf8");
const out =
  "// GENERATED by scripts/build-playbook.mjs from content/playbook/crossroads-playbook.html. Do not edit.\n" +
  `export const PLAYBOOK_HTML = ${JSON.stringify(html)};\n`;
writeFileSync(new URL("../lib/playbook-html.ts", import.meta.url), out);
console.log(`lib/playbook-html.ts written (${html.length} chars)`);
